-- =====================================================================
-- SAPPS Phase 3 seed — report template edits (Cris's notes, 9/29/2026)
--   * All 5 templates: new outcome list (item 1)
--   * All 5 templates: gender-neutral wording (item 2)
--   * Pre-Employment: position line (3), First Responder before Employment
--     (4), Employment wording (5), Finances cut back (6), Social Media
--     section (7), Evaluation wording (8), Traffic/Driving before Social
--     Media before Homeland Security (14)
-- Existing reports are NOT touched — they keep the text they were written
-- with. A full backup of the old templates is kept in
-- report_templates_backup_20260929.
-- =====================================================================

create table if not exists public.report_templates_backup_20260929 as
  select * from public.report_templates;
alter table public.report_templates_backup_20260929 enable row level security;

update public.report_templates
   set sections = $tpl$[{"title": "The Preparation", "body": "Per the documentation provided to our office, you requested _________________ be tested as part of the pre-employment screening application process for _____________________________."}, {"title": "The Pre-Test Interview Phase", "body": "Per your request, a Pre-Employment Polygraph Examination was administered to ______________, hereafter referred to as “Examinee.” The testing purpose and procedure was explained to Examinee, and Examinee consented to be interviewed and examined. Examinee reported being healthy and well-rested, and had not consumed alcohol or any illegal substances that would affect the examination.\n\nExaminee is applying for the position of __________."}, {"title": "Prior Polygraph Examination Information", "body": "Examinee has taken the following polygraph examinations prior to today’s date:\n\nMM/DD/YYYY – Agency – Examinee reported the result as “passed.”"}, {"title": "Identity / Education", "body": "Examinee was identified via a current driver’s license. Examinee reported being born in ____________. Examinee reported attending ______________ High School, graduating in ______. Examinee then attended ______________, graduating with a ______________ in ______. Examinee has never been suspended, banned or expelled from any educational institution."}, {"title": "Military History", "body": "Examinee reported never having enlisted in the United States Military."}, {"title": "First Responder Experience", "body": "Examinee reported having no first responder experience."}, {"title": "Employment History", "body": "Per the applicant polygraph screening booklet, Examinee reported the following employment history:\n\nUnless otherwise noted below, Examinee denied any disciplinary matters, theft, workplace violence, nor engaging in alcohol consumption, illegal drug use nor sexual activity at any place of employment.\n\nMM/DD/YYYY - Current: Examinee reported being employed by _______________ as a _______________.\n\nMM/DD/YYYY – MM/DD/YYYY: Examinee reported being employed by _______________ as a _______________."}, {"title": "Finances / Credits / Lawsuits", "body": "Examinee denied any prior wage garnishment, collections, delinquent tax payments, bankruptcy or anything else further remarkable to report."}, {"title": "Alcohol Consumption", "body": "Examinee reported first consuming alcohol at the age of __________. Examinee reported alcohol consumption on a (daily, weekly, monthly, social, rare) _________ basis. Examinee was last intoxicated on ______________. Examinee has never experienced a period of blacking out or memory loss due to alcohol consumption. Examinee stated never having experienced any alcohol related medical issues. Examinee reported no drinking related legal issues."}, {"title": "Illegal Drug Activity", "body": "Drug Type: First use. Last use. Frequency.\n\nExaminee denied personal use of any other illegal drugs and/or the improper use of any prescribed medication to include narcotics. Examinee further denied any sale or any profit of illegal drugs and/or narcotics; additionally, Examinee denied manufacturing, trafficking, distributing, transporting, growing or smuggling of any drugs illegally."}, {"title": "Serious Crimes", "body": "Examinee stated never having been arrested or charged with any criminal activity. Examinee reported never having engaged in any serious/felonious criminal behavior activity.\n\nExaminee reported the following misdemeanor/lesser criminal activity:\nWhat was stolen. How much was it worth. Approximate date."}, {"title": "Serious Crimes: Against Persons / Sex Crimes", "body": "During the pre-test interview it was understood between this Examiner and Examinee that a child, minor, and/or juvenile was someone under the age of eighteen. It was also understood that consensual sexual contact occurs without the use of force, excessive coercion, or the manipulation of someone who was too intoxicated to make a decision for themselves or unable to due to a mental condition. Examinee reported they understood that sexual contact between someone who held authority over another person was also non-consensual. Child pornography was defined as any depiction of sexually explicit conduct involving a minor (persons less than 18 years old) to include any photograph, film, video, picture, or computer-generated image or picture, whether made or produced by electronic, mechanical, or other means.\n\nExaminee reported the following sexual crimes:\n\nExaminee reported never having engaged in any illegal sexual behavior during their lifetime to include:\n\n- Sexual Contact with a Minor\n- Sexual Contact with Someone More Than Three Years Younger, While Still a Minor\n- Viewing, Possessing or Soliciting Child Pornography\n- Engaging in Sexual Contact Without the Consent of a Willing Partner\n- Sexual Contact with a Family Member\n- Exchanging Money for Sexual Contact\n- Sexual Contact with an Animal\n- Voyeuristic Behavior (Peeping, Exposing Oneself, Public Masturbation)\n- Sexual Conversations with a Minor After Reaching Adulthood"}, {"title": "Driving History", "body": "Examinee reported driving for _________ years and currently holds a valid __________ driver’s license.\n\nDriver’s License:\nExaminee reported the driver’s license has never been suspended.\n\nTraffic Citation/Accident:\nMM/DD/YYYY: Examinee was found guilty of _________. Examinee paid the ticket (Court Disposition).\n\nExaminee reported never having driven while under the influence of alcohol or an illegal substance."}, {"title": "Social Media", "body": "Examinee reported the following social media platforms currently or previously used by themselves or a third party on their behalf.\n\nExaminee denied the use of the internet or any social media platform for purposes of terrorist platforms, anti-government platforms, hate or bias towards any person or group, or a means to provide false, derogatory or humiliating information of a friend, coworker, supervisor, or employer."}, {"title": "Homeland Security", "body": "Examinee denied ever participating in any anti-government protest, nor ever being a member of a radical group or gang. Examinee denied ever holding any security clearance."}, {"title": "The Testing Phase", "body": "Test Objective: The relevant test questions noted below were designed to determine if Examinee appears truthful based on the information provided to this examiner.\n\nTest Procedure and Relevant Test Questions: A standardized, computerized polygraph examination was administered utilizing a standardized testing format. Noted below are the relevant-issue test questions asked during the testing phase and the Examinee’s test answers:\n\nRELEVANT: Q-1: Are you now withholding any information about your involvement with illegal drugs?\nANSWER: No\n\nRELEVANT: Q-2: Are you now concealing any information about your involvement with any serious crimes?\nANSWER: No\n\nRELEVANT: Q-3: Are you now withholding any information regarding any illegal sexual activity?\nANSWER: No\n\nRELEVANT: Q-4: Are you now purposefully falsifying or omitting any information in your polygraph booklet?\nANSWER: No"}, {"title": "The Evaluation Phase", "body": "Test Results: The direct examiner evaluated the examination utilizing nationally standardized scoring procedures. The reliability of the test data was determined by additional evaluations of the charts, test questions, and scoring procedures. The conclusion from those procedures is:\n\nNO SIGNIFICANT REACTIONS\n\nProfessional Opinion: Examinee’s answers to the relevant test questions are considered to be:\n\nNO DECEPTION INDICATED\n\n— OR (delete whichever block does not apply) —\n\nTest Results: The direct examiner evaluated the examination utilizing nationally standardized scoring procedures. The reliability of the test data was determined by additional evaluations of the charts, test questions, and scoring procedures to include a quality control process. The conclusion from those procedures is:\n\nSIGNIFICANT REACTIONS\n\nNumerical analysis of the individual Relevant Questions indicates Examinee was deceptive to Relevant Question #__, which addressed ______________________. Because of Examinee’s focus on Relevant Question #__, Examinee’s physiological responses to the remaining Relevant Questions may have been diminished or impaired and no opinion can be rendered regarding truthfulness or deception to those questions.\n\nProfessional Opinion: Examinee’s answers to the relevant test questions are considered to be:\n\nDECEPTION INDICATED"}, {"title": "The Post Test Phase", "body": "A post test interview was conducted. Examinee had no further statements or admissions. Examinee was advised that these statements and this report would be forwarded to ______________________________ after the quality control process."}]$tpl$::jsonb
 where name = 'Pre-Employment Report';

update public.report_templates
   set sections = (replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(sections::text, 'interfere with his ability', 'interfere with Examinee’s ability'), 'no change to his prescription medication', 'no change to Examinee’s prescription medication'), 'Examinee reported he is well rested', 'Examinee reported being well rested'), 'Examinee reported he was convicted of', 'Examinee reported being convicted of'), '. He was sentenced in', '. Examinee was sentenced in'), 'Upon his release on', 'Upon release on'), 'regarding his probation conditions', 'regarding Examinee’s probation conditions'), 'regarding his full sexual history', 'regarding Examinee’s full sexual history'), 'was his entire lifetime', 'was Examinee’s entire lifetime'), 'information he provided', 'information Examinee provided'), 'Examinee reported he currently meets with his supervising Probation Officer', 'Examinee reported currently meeting with the supervising Probation Officer'), 'Examinee stated he currently has no issues with his supervising officer', 'Examinee stated having no current issues with the supervising officer'), 'outside his given radius', 'outside the given radius'), 'with therapy, his counselor,', 'with therapy, the counselor,'), 'the victim of his offense', 'the victim of the offense'), 'Examinee reported he has not engaged', 'Examinee reported not having engaged'))::jsonb
 where name in ('Maintenance / Monitoring Report', 'Instant Offense Report', 'Sexual History Report', 'Specific Issue Report');

update public.report_templates
   set results = $res$["NO SIGNIFICANT REACTIONS / NO DECEPTION INDICATED", "SIGNIFICANT REACTIONS / DECEPTION INDICATED", "INCONCLUSIVE / NO OPINION", "INCONCLUSIVE / SUSPECTED COUNTERMEASURES", "TERMINATED"]$res$::jsonb;

-- Guard: fail the whole migration if any gendered pronoun survived.
do $$
declare bad text;
begin
  select string_agg(name, ', ') into bad from public.report_templates
   where sections::text ~* '\m(he|she|his|her|him|hers|himself|herself)\M';
  if bad is not null then raise exception 'Pronouns remain in: %', bad; end if;
end $$;
